    return {
        "k_factor": k_factor,
        "is_viral": is_exponential_viral,
        "organic_multiplier": multiplier,
        "seed_users": seed_users,
        "total_users_acquired": cumulative_users,
        "viral_bonus_users": cumulative_users - seed_users,
        "generations": generation_history
    }

